import { Dock } from "solen-design/react";

const items = [
  { icon: "🌐", label: "Browser", onClick: () => console.log("browser") },
  { icon: "✉️", label: "Mail", badge: 3, onClick: () => console.log("mail") },
  { separator: true },
  {
    icon: "⚙️",
    label: "Settings",
    menu: [
      { label: "General", shortcut: "⌘," },
      { label: "Appearance", items: [{ label: "Light" }, { label: "Dark" }] },
      { separator: true },
      { label: "Wi-Fi", checked: true }
    ]
  }
];

<div style={{ position: "relative", height: 400 }}>
  <Dock
    items={items}
    position="bottom"
    theme="dark"
    baseItemSize={50}
    magnification={70}
    distance={200}
    panelHeight={68}
    gap={10}
    roundness={0.5}
    bounce={true}
    autoHide={false}
    showLabels={true}
    showIndicators={true}
    showBadges={true}
    badgeColor="#ff453a"
    accentColor="#0a84ff"
  />
</div>
